(()=>{"use strict";const root=document.getElementById("api-playground");if(!root)return;const keyInput=root.querySelector("#pg-key");const actionSel=root.querySelector("#pg-action");const inboxWrap=root.querySelector("#pg-inbox-wrap");const inboxInput=root.querySelector("#pg-inbox");const runBtn=root.querySelector("#pg-run");const curlOut=root.querySelector("#pg-curl");const statusOut=root.querySelector("#pg-status");const respOut=root.querySelector("#pg-response");const apiBase=(root.dataset.apiBase||"").replace(/\/+$/,"");function needsInbox(){return actionSel.value==="wait"||actionSel.value==="messages";}
function syncInboxVisibility(){inboxWrap.hidden=!needsInbox();}
actionSel.addEventListener("change",syncInboxVisibility);syncInboxVisibility();function buildRequest(){const action=actionSel.value;const inboxId=(inboxInput.value||"").trim();if(action==="list"){return{method:"GET",path:"/api/v1/inboxes"};}
if(action==="create"){return{method:"POST",path:"/api/v1/inboxes",body:JSON.stringify({label:"playground"}),};}
if(action==="messages"){return{method:"GET",path:"/api/v1/inboxes/"+inboxId+"/messages"};}
if(action==="wait"){return{method:"GET",path:"/api/v1/inboxes/"+inboxId+"/messages/wait?require=otp&timeout=20",};}
return null;}
function renderCurl(req){let s="curl";if(req.method!=="GET")s+=" -X "+req.method;s+=' "'+apiBase+req.path+'"';s+=' \\\n  -H "Authorization: Bearer $MAILSOCKET_API_KEY"';if(req.body){s+=' \\\n  -H "Content-Type: application/json"';s+=" \\\n  -d '"+req.body+"'";}
curlOut.textContent=s;}
function setStatus(text,kind){statusOut.textContent=text;statusOut.className="pg-status"+(kind?" pg-"+kind:"");}
async function run(){const key=(keyInput.value||"").trim();const req=buildRequest();if(!req)return;if(needsInbox()&&!(inboxInput.value||"").trim()){respOut.textContent="";setStatus("Enter an inbox id first (e.g. inbox_...).","err");return;}
renderCurl(req);if(!key){respOut.textContent="";setStatus("Enter an API key (ms_live_...) to run against the live API.","err");return;}
runBtn.disabled=true;setStatus("Running…","");respOut.textContent="";const started=Date.now();try{const opts={method:req.method,headers:{Authorization:"Bearer "+key},};if(req.body){opts.headers["Content-Type"]="application/json";opts.body=req.body;}
const res=await fetch(req.path,opts);const ms=Date.now()-started;const ct=res.headers.get("content-type")||"";let bodyText;if(res.status===204){bodyText="(204 No Content — no message yet; call again to keep polling.)";}else if(ct.indexOf("application/json")!==-1){const json=await res.json();bodyText=JSON.stringify(json,null,2);}else{bodyText=await res.text();}
respOut.textContent=bodyText;const kind=res.ok?"ok":"err";setStatus("HTTP "+res.status+" · "+ms+" ms",kind);}catch(err){setStatus("Request failed: "+(err&&err.message?err.message:err),"err");}finally{runBtn.disabled=false;}}
runBtn.addEventListener("click",run);actionSel.addEventListener("change",()=>{const r=buildRequest();if(r)renderCurl(r);});inboxInput.addEventListener("input",()=>{const r=buildRequest();if(r)renderCurl(r);});const first=buildRequest();if(first)renderCurl(first);})();
